add_shortcode( 'product_description', 'perfectpixel_product_description_shortcode' );

function perfectpixel_product_description_shortcode( $atts ) {
	$atts    = shortcode_atts( array( 'id' => 0, 'short' => 'no' ), $atts );
	$product = wc_get_product( absint( $atts['id'] ) ? absint( $atts['id'] ) : get_the_ID() );
	if ( ! $product || 'publish' !== $product->get_status() ) {
		return '';
	}
	$text = 'yes' === $atts['short'] ? $product->get_short_description() : $product->get_description();
	// Avoid infinite loops if the description itself contains this shortcode.
	$text = str_replace( '[product_description', '[ product_description', $text );
	return '<div class="perfectpixel-product-description">' . wp_kses_post( wpautop( do_shortcode( $text ) ) ) . '</div>';
}
